import re
from typing import Union
import datetime

def _parse_tz_offset(tz_offset: Union[datetime.timedelta, float, str]) -> datetime.timedelta:
    if isinstance(tz_offset, datetime.timedelta):
        return tz_offset
    elif isinstance(tz_offset, str):
        # Parse string offset of the form "+HH:MM" or "-HH:MM"
        match = re.match(r'^([+-])(\d{1,2}):(\d{2})$', tz_offset)
        if not match:
            raise ValueError(f"Invalid timezone offset format: {tz_offset}. Expected '+HH:MM' or '-HH:MM'")

        sign, hours, minutes = match.groups()
        total_minutes = int(hours) * 60 + int(minutes)
        if sign == '-':
            total_minutes = -total_minutes

        return datetime.timedelta(minutes=total_minutes)
